proposals.content:
service: hello
workloads:
  - namespace: hello
    selector: app=hello
    container: hello
    clusters: all
    stack:
      mesh:       {is: "Istio 1.31.1, sidecar mode, PeerAuthentication mTLS STRICT", verify: "pilot_info returns a series; kube_namespace_labels{namespace=\"hello\"} has label_istio_injection=\"enabled\""}
      deploy:     {is: "Argo Rollouts canary with a Prometheus AnalysisTemplate; Argo CD syncs deploy/envs/<env> from main", verify: "kube_replicaset_owner{namespace=\"hello\"} has owner_kind=\"Rollout\"; deploy/base/rollout.yaml declares kind: Rollout"}
      admission:  {is: "Kubernetes Pod Security Admission at restricted; webhooks istio-sidecar-injector, istiod-default-validator, keda-admission", verify: "kube_namespace_labels{namespace=\"hello\"} has label_pod_security_kubernetes_io_enforce=\"restricted\""}
      enforcer:   {is: "Kubernetes NetworkPolicy, default-deny plus explicit allows; the implementing CNI is not identifiable from metrics", verify: "kube_networkpolicy_spec_ingress_rules{namespace=\"hello\"} lists default-deny and allow-platform"}
      autoscaler: {is: "KEDA ScaledObject on sum(vikrant_inflight_rpcs), shadow HPA keda-hpa-hello", verify: "kube_horizontalpodautoscaler_info{namespace=\"hello\"} has horizontalpodautoscaler=\"keda-hpa-hello\""}
      metrics:    {is: "Prometheus; families vikrant_rpcs_handled_total, vikrant_inflight_rpcs, vikrant_unary_latency_seconds_bucket, istio_requests_total, envoy_http_rbac; no alerting rules loaded", verify: "vikrant_inflight_rpcs{namespace=\"hello\"} returns data; metrics_rules() group list is non-empty"}
docs:
  - README.md
